package com.pathstudy.assessment.domain;
import com.pathstudy.curriculum.domain.AuditedEntity; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal;
@Entity @Table(name="assessment_items",uniqueConstraints={@UniqueConstraint(name="uk_assessment_item_version_sequence",columnNames={"assessment_version_id","sequence_no"}),@UniqueConstraint(name="uk_assessment_item_version_question",columnNames={"assessment_version_id","question_version_id"})},indexes={@Index(name="idx_assessment_item_version",columnList="assessment_version_id"),@Index(name="idx_assessment_item_question",columnList="question_version_id")}) @Getter @Setter @NoArgsConstructor public class AssessmentItem extends AuditedEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="assessment_version_id",nullable=false) private AssessmentVersion assessmentVersion; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="question_version_id",nullable=false) private QuestionVersion questionVersion; @Column(name="sequence_no",nullable=false) private int sequenceNo; @Column(nullable=false,precision=10,scale=2) private BigDecimal points=BigDecimal.ONE; @Column(nullable=false) private boolean required=true; }
